    es: zhaoGuide({
      title: "Zhao Yun y A Dou: Defensa de tinta", gameplay: "Defensa estratégica de fusiones", difficulty: "Fácil de aprender y cada vez más exigente", time: "Aproximadamente 1–3 minutos por misión", genre: ["Estrategia", "Defensa", "Fusión"], skills: ["Planificación", "Ritmo", "Adaptación"],
      intro: "Recluta soldados-caracteres, repártelos entre tres líneas y fusiona unidades iguales para proteger a A Dou en 30 breves misiones de tinta.",
      story: ["El frente de tinta alrededor de A Dou está cediendo. Zhao Yun debe reconstruir la formación durante una batalla corta y sostener las tres líneas.", "Cada carácter es un símbolo claro de unidad; la decisión real es dónde colocarlo, cuándo fusionarlo y cuándo gastar una habilidad de general."],
      systems: ["Reclutar cuesta tres raciones y coloca la siguiente unidad en el primer hueco libre; las raciones se recuperan durante la batalla.", "Selecciona dos unidades iguales del mismo nivel para fusionarlas. Dos unidades de nivel tres ascienden al general correspondiente.", "Cada espacio pertenece a una de tres líneas. Las unidades atacan automáticamente, pero tú decides la cobertura y el momento de fusionar.", "Los cuatro generales ofrecen corte, aturdimiento, carga o flechas múltiples; cada habilidad tiene un enfriamiento visible y exige activación manual.", "El Resultado aparece dentro de Batalla y permite volver al mapa, entrar en la siguiente misión o repetir la actual."],
      how: ["Entra en una misión desbloqueada y lee el objetivo de las tres líneas.", "Recluta cuando haya un hueco seguro y fusiona dos unidades iguales.", "Mueve una unidad a una línea sin defensa y conserva cobertura antes de una fusión arriesgada.", "Usa una habilidad preparada cuando un jefe o enemigo rápido amenace una línea.", "Derrota todas las oleadas y el puesto enemigo. Si la salud de A Dou llega a cero, cambia la formación y reintenta."],
      strategyTips: ["Una unidad fuerte no compensa una línea vacía.", "Observa por qué línea llega el enemigo antes de elegir entre cubrir o fusionar.", "Reserva la habilidad del general para un pico de presión visible.", "Los capítulos posteriores añaden velocidad, resistencia, presión dividida y jefes, no reglas ocultas."],
      progression: ["Las 30 misiones se dividen en seis capítulos que aumentan la presión, la resistencia y la frecuencia de jefes.", "La mejor puntuación de estrellas se guarda solo en este navegador; no hay cuenta ni clasificación."],
      designNote: "Es una defensa de fusiones original de WeightPlay con misiones, campo, controles, texto y arte de tinta propios.",
      parent: "No hay cuenta, compras, chat, clasificación ni publicidad. El progreso se guarda solo en este navegador.",
      faq: [["¿Qué significan los caracteres?", "Son símbolos de cuatro tipos de unidad con distinto daño y ritmo de ataque; no son una prueba de vocabulario."], ["¿Cómo aparece un general?", "Fusiona dos unidades iguales de nivel tres para obtener el general de ese tipo."], ["¿Puedo perder tras una fusión potente?", "Sí. La fusión aumenta el daño, pero puede dejar una línea vacía; revisa la cobertura primero."], ["¿Se guarda el progreso?", "Sí. Las misiones superadas y las mejores estrellas se guardan solo en este navegador."]],
    }),
